using ProyectoFinal.Services; namespace ProyectoFinal.Views; public partial class StatisticsPage:ContentPage { readonly ProductStore store=new(); public StatisticsPage(){InitializeComponent();} protected override async void OnAppearing(){base.OnAppearing();var p=await store.GetAsync();Consumed.Text=p.Count(x=>x.IsConsumed).ToString();Active.Text=p.Count(x=>!x.IsConsumed).ToString();} async void LocationClicked(object s,EventArgs e){try{var location=await Geolocation.Default.GetLocationAsync(new GeolocationRequest(GeolocationAccuracy.Medium));LocationStatus.Text=location is null?"No se obtuvo ubicación.":$"Ubicación registrada: {location.Latitude:F3}, {location.Longitude:F3}";}catch{LocationStatus.Text="Debes permitir el acceso a la ubicación.";}} }
